rows.union partial specialization:
template <class T, class U> union S { T t; U u; };
template <class T> union S<T, int> { T t; int u; char c[3]; };
S<char, int> s{};
static_assert(sizeof(S<char, int>) >= sizeof(int));

rows.union explicit specialization:
template <class T> union S { T t; };
template <> union S<int> { int a; long b; };
static_assert(sizeof(S<int>) == sizeof(long));

rows.union partial specialization with final:
template <class T> union S { T t; };
template <class T> union S<T*> final { T* p; long n; };
S<int*> s{};

rows.union defined with a namespace qualifier:
namespace N { union V; }
union N::V { int a; float f; };
N::V v{1};

rows.union defined with a class qualifier:
struct O { union I; };
union O::I { int x; };
O::I i{2};

rows.member union template defined outside:
